import test from 'node:test';
import assert from 'node:assert/strict';
import { buildHkdfLabel, hkdfExpandLabel } from '../dist/reference-tls-key-schedule.js';
// Published RFC 8448 section 3, server application write traffic keys.
// Expected values copied from the RFC, not generated by this implementation.
const prk = Buffer.from('a11af9f05531f856ad47116b45a950328204b4f44bfb6b3a4b4f1f3fcb631643', 'hex');
test('RFC 8448 application traffic key uses Expand without Extract', () => {
  assert.equal(Buffer.from(hkdfExpandLabel(prk, 'key', new Uint8Array(), 16)).toString('hex'), '9f02283b6c9c07efc26bb9f2ac92e356');
});
test('RFC 8448 application IV and exact label encoding', () => {
  assert.equal(Buffer.from(hkdfExpandLabel(prk, 'iv', new Uint8Array(), 12)).toString('hex'), 'cf782b88dd83549aadf1e984');
  assert.equal(Buffer.from(buildHkdfLabel('key', new Uint8Array(), 16)).toString('hex'), '001009746c733133206b657900');
});
test('HKDF label rejects overflow, fractional lengths and UTF-8 byte overflow', () => {
  for (const length of [-1, 65536, 1.5, NaN, Infinity]) assert.throws(() => buildHkdfLabel('key', new Uint8Array(), length), /INVALID_HKDF_LABEL/);
  assert.throws(() => buildHkdfLabel('a'.repeat(250), new Uint8Array(), 32), /INVALID_HKDF_LABEL/);
  assert.throws(() => buildHkdfLabel('é'.repeat(125), new Uint8Array(), 32), /INVALID_HKDF_LABEL/);
  assert.throws(() => buildHkdfLabel('key', new Uint8Array(256), 32), /INVALID_HKDF_LABEL/);
  assert.equal(buildHkdfLabel('a'.repeat(249), new Uint8Array(255), 65535).length, 514);
});
test('SHA-256 HKDF expansion permits its maximum and rejects excess output', () => {
  assert.equal(hkdfExpandLabel(prk, 'test', new Uint8Array(), 8160).length, 8160);
  assert.throws(() => hkdfExpandLabel(prk, 'test', new Uint8Array(), 8161));
});
